var i=`1363-tamales-tolimenses`;var a=`world-1363`;var n=`CO`;var s=`south-america`;var o=8;var r=150;var l={en:`Tamales Tolimenses`,ua:`Тамалес толіменсес`};var g={en:`Tamales Tolimenses is a dish from Colombia featuring masa harina, chicken thigh, potato, carrot. This home-sized recipe records each ingredient at the step where it is used.`,ua:`Тамалес толіменсес, страва кухні країни Колумбія з такими основними складниками: маса харіна, куряче стегно, картопля, морква. У домашньому рецепті кожний продукт прив’язаний до етапу його використання.`};var h=[{en:`Mix the corn flour with the measured water and salt until a soft cohesive, non-sticky masa forms. Rest covered for about 10 minutes; this gluten-free dough does not become elastic like wheat dough.`,ua:`Змішайте кукурудзяне борошно із зазначеною водою й сіллю до м’якої цілісної маси, що не липне. Накрийте на приблизно 10 хвилин; таке безглютенове тісто не стає еластичним, як пшеничне.`,t:[`mixing`,`kneading`,`resting-dough`],m:13,i:[[`masa-harina`,530,`g`],[`chicken-stock`,450,`ml`],[`lard`,130,`g`]]},{en:`Combine the remaining ingredients, cover partly and stew gently for about 28 minutes until the flavors meld and everything is tender.`,ua:`З’єднайте решту складників, частково накрийте й тушкуйте приблизно 28 хвилин до поєднання смаків і м’якості продуктів.`,t:[`stewing`],m:28,i:[[`chicken-thigh`,620,`g`],[`potato`,250,`g`],[`carrot`,170,`g`],[`tomato`,240,`g`]]},{en:`Place a portion of prepared filling on each leaf or wrapper, tuck in the sides and roll tightly into neat parcels.`,ua:`Викладіть порцію готової начинки на кожен листок або обгортку, загорніть боки й скрутіть щільні акуратні рулетики.`,t:[`rolling-stuffed-food`],m:16,i:[[`banana-leaf`,9,`leaf`]]},{en:`Steam the already prepared parcels or mixture over gently boiling water for approximately 90 minutes, until fully cooked or set.`,ua:`Готуйте раніше підготовлені згортки або масу на парі над слабким кипінням близько 90 хвилин до готовності.`,t:[`steaming`],m:90,i:[]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:3,i:[[`cilantro`,25,`g`]]}];var m={slug:i,id:a,country:`CO`,region:s,servings:8,minutes:150,title:l,text:g,steps:h};export{n as country,m as default,a as id,r as minutes,s as region,o as servings,i as slug,h as steps,g as text,l as title};